import {
  ArrowLeft,
  ArrowRight,
  BookOpenText,
  BookmarkPlus,
  Check,
  CircleHelp,
  Layers3,
  RotateCcw,
  Sparkles,
} from "lucide-react";
import {
  useEffect,
  useMemo,
  useState,
  type CSSProperties,
} from "react";
import { Navigate, useNavigate, useParams } from "react-router-dom";
import type { PracticeItem } from "@inkflow/shared";
import { cn } from "../../lib/cn";
import {
  knowledgeAttemptsForBook,
  knowledgeMasteryByBook,
  useKnowledge,
} from "../../store/knowledge";
import { recordStudyEvent } from "../home/studyLog";
import SpotlightCard from "../reactbits/vendor/SpotlightCard/SpotlightCard";
import {
  knowledgeBookById,
  nodesForBook,
  practiceForBook,
} from "./knowledgeCatalog";
import "./knowledge.css";

type BookTab = "overview" | "map" | "reading";

function normalizeAnswer(value: string) {
  return value
    .trim()
    .toLowerCase()
    .replace(/[.!?。！？]+$/g, "")
    .replace(/\s+/g, " ");
}

function isCorrectAnswer(item: PracticeItem, answer: string) {
  const normalized = normalizeAnswer(answer);
  return [item.answer, ...item.acceptedAnswers].some(
    (candidate) => normalizeAnswer(candidate) === normalized,
  );
}

export function KnowledgeBookPage() {
  const { bookId } = useParams();
  const navigate = useNavigate();
  const book = knowledgeBookById(bookId);
  const hydrate = useKnowledge((state) => state.hydrate);
  const cards = useKnowledge((state) => state.cards);
  const attempts = useKnowledge((state) => state.attempts);
  const addNodeCard = useKnowledge((state) => state.addNodeCard);
  const recordAttempt = useKnowledge((state) => state.recordAttempt);
  const [tab, setTab] = useState<BookTab>("overview");
  const [selectedModuleId, setSelectedModuleId] = useState<string | null>(null);
  const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null);
  const [practiceIndex, setPracticeIndex] = useState(0);
  const [answer, setAnswer] = useState("");
  const [feedback, setFeedback] = useState<string | null>(null);
  const [feedbackCorrect, setFeedbackCorrect] = useState<boolean | null>(null);
  const [practiceOpen, setPracticeOpen] = useState(false);

  useEffect(() => {
    void hydrate();
  }, [hydrate]);

  useEffect(() => {
    if (!book) return;
    recordStudyEvent({
      kind: "open",
      at: Date.now(),
      bookId: book.id,
    });
  }, [book]);

  useEffect(() => {
    setSelectedModuleId(book?.modules[0]?.id ?? null);
    setSelectedNodeId(null);
    setPracticeIndex(0);
    setAnswer("");
    setFeedback(null);
    setFeedbackCorrect(null);
  }, [book]);

  const practiceItems = useMemo(() => {
    if (!book) return [];
    const selectedModule = book.modules.find(
      (module) => module.id === selectedModuleId,
    );
    if (selectedNodeId) {
      const selectedNode = nodesForBook(book).find(
        (node) => node.id === selectedNodeId,
      );
      return selectedNode?.practice ?? [];
    }
    if (selectedModule) {
      return selectedModule.nodes.flatMap((node) => node.practice);
    }
    return practiceForBook(book);
  }, [book, selectedModuleId, selectedNodeId]);

  useEffect(() => {
    setPracticeIndex(0);
    setAnswer("");
    setFeedback(null);
    setFeedbackCorrect(null);
  }, [selectedModuleId, selectedNodeId]);

  if (!book) return <Navigate to="/library" replace />;

  const nodes = nodesForBook(book);
  const bookCards = cards.filter((card) => card.bookId === book.id);
  const bookAttempts = knowledgeAttemptsForBook(attempts, book.id);
  const correctAttempts = bookAttempts.filter((attempt) => attempt.correct).length;
  const accuracy = bookAttempts.length
    ? Math.round((correctAttempts / bookAttempts.length) * 100)
    : 0;
  const progress = knowledgeMasteryByBook(cards, book.id);
  const selectedModule =
    book.modules.find((module) => module.id === selectedModuleId) ??
    book.modules[0];
  const selectedNode = selectedNodeId
    ? nodes.find((node) => node.id === selectedNodeId)
    : undefined;
  const currentPractice = practiceItems[practiceIndex];

  const submitPractice = () => {
    if (!currentPractice || !answer.trim()) return;
    const correct = isCorrectAnswer(currentPractice, answer);
    setFeedbackCorrect(correct);
    setFeedback(
      `${correct ? "Correct. " : "Not quite. "}${currentPractice.explanationZh}`,
    );
    recordAttempt(currentPractice, book.id, answer, correct);
    recordStudyEvent({
      kind: "knowledge-review",
      at: Date.now(),
      bookId: book.id,
      nodeId: currentPractice.nodeId,
      correct,
    });
  };

  const movePractice = () => {
    if (practiceItems.length === 0) return;
    setPracticeIndex((current) => (current + 1) % practiceItems.length);
    setAnswer("");
    setFeedback(null);
    setFeedbackCorrect(null);
  };

  return (
    <main
      className="knowledge-book-page"
      style={
        {
          "--book-accent": book.accent,
          "--book-secondary": book.secondary,
        } as CSSProperties
      }
    >
      <header className="knowledge-book-page__header">
        <button
          type="button"
          className="knowledge-icon-button"
          onClick={() => navigate(`/library/${book.categoryId}`)}
          aria-label="返回分类"
        >
          <ArrowLeft size={18} />
        </button>
        <div>
          <span className="knowledge-eyebrow">
            {book.categoryId} · Primary volume
          </span>
          <h1>{book.title}</h1>
          <p>
            {book.zhTitle} · {book.summaryZh}
          </p>
        </div>
        <span className="knowledge-library__count">
          <Layers3 size={15} />
          {book.modules.length} modules
        </span>
      </header>

      <div className="knowledge-book-page__body">
        <div className="knowledge-book-page__main">
          <nav className="knowledge-tabs" aria-label="书本功能">
            {(
              [
                ["overview", "Overview"],
                ["map", "Knowledge Map"],
                ["reading", "Reading"],
              ] as const
            ).map(([id, label]) => (
              <button
                type="button"
                key={id}
                className={cn(tab === id && "is-active")}
                onClick={() => setTab(id)}
              >
                {label}
              </button>
            ))}
          </nav>

          <section className="knowledge-view">
            {tab === "overview" ? (
              <div className="knowledge-overview">
                <article className="knowledge-overview__hero">
                  <span className="knowledge-eyebrow">Leafia Knowledge</span>
                  <h2>{book.title}</h2>
                  <p>{book.summaryZh}</p>
                </article>
                <div className="knowledge-metrics">
                  <div className="knowledge-metric">
                    <strong>{book.modules.length}</strong>
                    <small>modules</small>
                  </div>
                  <div className="knowledge-metric">
                    <strong>{nodes.length}</strong>
                    <small>knowledge nodes</small>
                  </div>
                  <div className="knowledge-metric">
                    <strong>{progress}%</strong>
                    <small>mastery progress</small>
                  </div>
                  <div className="knowledge-metric">
                    <strong>{accuracy}%</strong>
                    <small>practice accuracy</small>
                  </div>
                </div>
                <article className="knowledge-module">
                  <header>
                    <div>
                      <span className="knowledge-eyebrow">Recent focus</span>
                      <h3>{selectedModule?.title ?? "Start here"}</h3>
                    </div>
                    <p>{selectedModule?.coreQuestion}</p>
                  </header>
                  <div className="knowledge-node-grid">
                    {selectedModule?.nodes.map((node) => (
                      <SpotlightCard
                        key={node.id}
                        className="knowledge-node"
                        as="button"
                        spotlightColor="rgba(47, 135, 171, 0.11)"
                        onClick={() => {
                          setSelectedNodeId(node.id);
                          setTab("map");
                        }}
                      >
                        <span>{node.type}</span>
                        <strong>{node.title}</strong>
                        <em>{node.titleZh}</em>
                        <p>{node.summaryZh}</p>
                        <footer>
                          <span>{node.practice.length} questions</span>
                          <ArrowRight size={14} />
                        </footer>
                      </SpotlightCard>
                    ))}
                  </div>
                </article>
              </div>
            ) : tab === "map" ? (
              <div className="knowledge-map">
                {book.modules.map((module) => (
                  <article className="knowledge-module" key={module.id}>
                    <header>
                      <div>
                        <span className="knowledge-eyebrow">
                          {module.nodes.length} nodes
                        </span>
                        <h3>{module.title}</h3>
                        <p>{module.titleZh}</p>
                      </div>
                      <p>{module.coreQuestion}</p>
                    </header>
                    <div className="knowledge-node-grid">
                      {module.nodes.map((node) => {
                        const saved = bookCards.some(
                          (card) => card.nodeId === node.id,
                        );
                        return (
                          <SpotlightCard
                            key={node.id}
                            className="knowledge-node"
                            as="button"
                            spotlightColor="rgba(47, 135, 171, 0.11)"
                            onClick={() => {
                              setSelectedModuleId(module.id);
                              setSelectedNodeId(node.id);
                            }}
                          >
                            <span>{node.type}</span>
                            <strong>{node.title}</strong>
                            <em>{node.titleZh}</em>
                            <p>{node.summaryZh}</p>
                            <footer>
                              <span>{node.practice.length} questions</span>
                              <span>
                                {saved ? <Check size={14} /> : null}
                              </span>
                            </footer>
                          </SpotlightCard>
                        );
                      })}
                    </div>
                  </article>
                ))}
              </div>
            ) : (
              <article className="knowledge-book-page__reading">
                <span className="knowledge-eyebrow">Guided source reading</span>
                <h2>{selectedNode?.title ?? selectedModule?.title}</h2>
                <p>
                  {selectedNode?.keyIdea ??
                    selectedModule?.coreQuestion ??
                    "从知识地图选择一个节点开始阅读。"}
                </p>
                <div className="knowledge-source-list">
                  {(selectedNode
                    ? [selectedNode]
                    : selectedModule?.nodes ?? []
                  ).map((node) => (
                    <span key={node.id}>
                      <strong>{node.title}: </strong>
                      {node.keyPoints.join(" · ")}
                    </span>
                  ))}
                </div>
                <div className="knowledge-source-list">
                  {book.sources.map((source) => (
                    <span key={source}>{source}</span>
                  ))}
                </div>
              </article>
            )}
          </section>
        </div>

        <aside
          className="knowledge-practice-rail"
          aria-label="书本知识复习"
          data-open={practiceOpen ? "true" : "false"}
        >
          <button
            type="button"
            className="knowledge-practice-drawer-toggle"
            onClick={() => setPracticeOpen((value) => !value)}
            aria-expanded={practiceOpen}
          >
            <Sparkles size={15} />
            {practiceOpen ? "收起练习" : "打开书本练习"}
          </button>
          <span className="knowledge-eyebrow">Contextual review</span>
          <h2>Practice</h2>
          <p>
            只复习当前主书。选择模块练综合题，或选择知识点集中练 3 至 6 题。
          </p>

          <div className="knowledge-practice-scope">
            {book.modules.map((module) => (
              <button
                type="button"
                key={module.id}
                className={cn(
                  module.id === selectedModuleId &&
                    !selectedNodeId &&
                    "is-active",
                )}
                onClick={() => {
                  setSelectedModuleId(module.id);
                  setSelectedNodeId(null);
                }}
              >
                {module.titleZh}
              </button>
            ))}
          </div>

          {selectedModule ? (
            <div className="knowledge-practice-scope">
              {selectedModule.nodes.map((node) => (
                <button
                  type="button"
                  key={node.id}
                  className={cn(node.id === selectedNodeId && "is-active")}
                  onClick={() => setSelectedNodeId(node.id)}
                >
                  {node.titleZh}
                </button>
              ))}
            </div>
          ) : null}

          <div className="knowledge-rail-actions">
            <button
              type="button"
              className="knowledge-secondary-button"
              disabled={!selectedNode}
              onClick={() => {
                if (!selectedNode) return;
                const card = addNodeCard(book.id, selectedNode.id);
                if (card) {
                  recordStudyEvent({
                    kind: "card-created",
                    at: Date.now(),
                    cardId: card.id,
                    categoryId: book.categoryId,
                  });
                  setTab("map");
                }
              }}
            >
              <BookmarkPlus size={15} />
              收藏知识点
            </button>
            <button
              type="button"
              className="knowledge-secondary-button"
              onClick={() => navigate("/practice")}
            >
              <Sparkles size={15} />
              练习中心
            </button>
          </div>

          {currentPractice ? (
            <article className="knowledge-question">
              <span className="knowledge-eyebrow">
                Question {practiceIndex + 1} / {practiceItems.length} ·{" "}
                {currentPractice.kind}
              </span>
              <strong>{currentPractice.prompt}</strong>
              {currentPractice.options.length > 0 ? (
                currentPractice.options.map((option) => (
                  <label key={option}>
                    <input
                      type="radio"
                      name={currentPractice.id}
                      checked={answer === option}
                      onChange={() => {
                        setAnswer(option);
                        setFeedback(null);
                        setFeedbackCorrect(null);
                      }}
                    />
                    <span>{option}</span>
                  </label>
                ))
              ) : (
                <input
                  type="text"
                  value={answer}
                  onChange={(event) => {
                    setAnswer(event.target.value);
                    setFeedback(null);
                    setFeedbackCorrect(null);
                  }}
                  placeholder="Write your answer…"
                  onKeyDown={(event) => {
                    if (event.key === "Enter") submitPractice();
                  }}
                />
              )}
              {feedback ? (
                <div
                  className={cn(
                    "knowledge-question__feedback",
                    feedbackCorrect === false && "is-wrong",
                  )}
                >
                  {feedback}
                </div>
              ) : null}
              <div className="knowledge-rail-actions">
                {feedback ? (
                  <button
                    type="button"
                    className="knowledge-primary-button"
                    onClick={movePractice}
                  >
                    <RotateCcw size={14} />
                    Next question
                  </button>
                ) : (
                  <button
                    type="button"
                    className="knowledge-primary-button"
                    disabled={!answer.trim()}
                    onClick={submitPractice}
                  >
                    <CircleHelp size={14} />
                    Check answer
                  </button>
                )}
              </div>
            </article>
          ) : (
            <div className="knowledge-empty">
              <BookOpenText size={20} />
              <strong>选择模块或知识点</strong>
              <p>题目只从当前书籍生成。</p>
            </div>
          )}
        </aside>
      </div>
    </main>
  );
}
