import { useEffect, useMemo, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { useThemeStore } from "../../store/theme";
import { THEME_PRESETS } from "../../theme/palettes";
import StaggeredMenu from "../reactbits/vendor/StaggeredMenu/StaggeredMenu";
import "./persistent-dock.css";

/**
 * The right-hand plaque names the three spaces the room is made of, the way a
 * study is signed rather than navigated: LIBRARY is where the knowledge lives,
 * PIANO is how it comes back, DRAWER is where it is kept.
 *
 * `zh` carries the Chinese name under the English one, and `caption` is the
 * one-line inventory of what the space holds. Both exist so the plaque reads
 * as a room sign — not as a web menu with a list of links.
 */
const directory = [
  {
    label: "LIBRARY",
    zh: "知识库",
    caption: "English knowledge",
    ariaLabel: "Library — English knowledge",
    children: [
      {
        label: "Linguistics",
        ariaLabel: "Open Linguistics",
        path: "/library/linguistics",
      },
      {
        label: "Literature",
        ariaLabel: "Open Literature",
        path: "/library/literature",
      },
      {
        label: "Culture",
        ariaLabel: "Open Culture",
        path: "/library/culture",
      },
      {
        label: "Translation",
        ariaLabel: "Open Translation",
        path: "/library/translation",
      },
      {
        label: "Vocabulary",
        ariaLabel: "Open Vocabulary",
        path: "/library/vocabulary",
      },
      {
        label: "Writing",
        ariaLabel: "Open Writing",
        path: "/library/writing",
      },
    ],
  },
  {
    label: "PIANO",
    zh: "练习",
    caption: "Practice",
    ariaLabel: "Piano — practice",
    children: [
      {
        label: "Concepts",
        ariaLabel: "Practice concepts",
        path: "/book/knowledge-linguistics",
      },
      {
        label: "Vocabulary",
        ariaLabel: "Practice vocabulary",
        path: "/vocabulary",
      },
      {
        label: "Translation",
        ariaLabel: "Practice translation",
        path: "/book/knowledge-translation",
      },
      {
        label: "Writing",
        ariaLabel: "Practice writing",
        path: "/book/knowledge-writing",
      },
    ],
  },
  {
    label: "DRAWER",
    zh: "我的知识库",
    caption: "My archive",
    ariaLabel: "Drawer — my archive",
    children: [
      {
        label: "Recent",
        ariaLabel: "Open recent learning drawer",
        path: "/shelf?drawer=notes",
      },
      {
        label: "Knowledge",
        ariaLabel: "Open knowledge cards drawer",
        path: "/shelf?drawer=materials",
      },
      {
        label: "Words",
        ariaLabel: "Open vocabulary review drawer",
        path: "/shelf?drawer=collection",
      },
    ],
  },
] as const;

function isActive(pathname: string, search: string, path: string) {
  if (path.includes("?")) {
    const [targetPath, targetSearch] = path.split("?");
    return pathname === targetPath && search === `?${targetSearch}`;
  }
  if (path === "/library") {
    return pathname === "/library" || pathname.startsWith("/book/");
  }
  return pathname === path || pathname.startsWith(`${path}/`);
}

export function PersistentDock() {
  const location = useLocation();
  const navigate = useNavigate();
  const [menuSignal, setMenuSignal] = useState(0);
  const [dismissed, setDismissed] = useState(false);
  const themeId = useThemeStore((state) => state.themeId);
  const theme = THEME_PRESETS[themeId];
  // The landing has its own nav and runs its own scroll choreography.
  const onLanding = location.pathname === "/";
  const onShelf = location.pathname === "/shelf";

  useEffect(() => {
    const openMenu = () => {
      setDismissed(false);
      setMenuSignal((current) => current + 1);
    };
    window.addEventListener("inkflow:open-menu", openMenu);
    return () => window.removeEventListener("inkflow:open-menu", openMenu);
  }, []);

  const menuItems = useMemo(
    () =>
      directory.map((item) => ({
        label: item.label,
        zh: item.zh,
        caption: item.caption,
        ariaLabel: item.ariaLabel,
        link: "#",
        children: item.children.map((child) => ({
          label: child.label,
          ariaLabel: child.ariaLabel,
          link: child.path,
          className: isActive(location.pathname, location.search, child.path)
            ? "is-active"
            : undefined,
        })),
      })),
    [location.pathname, location.search],
  );

  if (onLanding) return null;

  return (
    <StaggeredMenu
      className="inkflow-staggered-menu"
      isFixed
      position="right"
      items={menuItems}
      colors={[
        theme.tokens.pageStart,
        theme.tokens.pageMid,
        theme.tokens.pageEnd,
      ]}
      accentColor={theme.tokens.accentDeep}
      displaySocials={false}
      displayItemNumbering={false}
      menuButtonColor={theme.tokens.onAccent}
      openMenuButtonColor={theme.tokens.onAccent}
      logoUrl="/leafia-mark.svg"
      hideToggle={onShelf}
      openSignal={menuSignal}
      dismissed={dismissed}
      onItemClick={(item) => {
        const targetPath = item.link;
        if (!targetPath.startsWith("/")) return;
        setDismissed(true);
        if (targetPath.startsWith("/shelf?drawer=")) {
          window.dispatchEvent(
            new CustomEvent("inkflow:shelf-action", {
              detail: { path: targetPath, at: Date.now() },
            }),
          );
        }
        navigate(targetPath);
      }}
    />
  );
}
